<template>
  <div class="flex flex-col gap-2">
    <h3 v-if="title" class="text-xl font-semibold">{{ title }}</h3>
    <div class="flex flex-col gap-2">
      <AppEmpty v-if="items.length === 0" variant="table" subject="valid signatures" />
      <template v-else>
        <NuxtLink v-for="item in items" :key="item.id" :to="getItemLink(item)">
          <BallotsSignaturesListItem
            :item="item"
            :highlighted-signature-id="highlightedSignatureId"
            @signature-item-click="$emit('signature-item-click', item.id)"
          />
        </NuxtLink>
      </template>
    </div>
  </div>
</template>

<script setup lang="ts">
import type { ValidSignatureShortInfo, SubmittedSignatureDetails, SubmittedSignatureShortInfo } from '~/client';
import type { TypedNuxtLink } from '#build/typed-router/typed-router';
import { isSubmittedSignatureDetails } from '~/utils/typeCheckers/signatures';

interface Props {
  title?: string;
  items: ValidSignatureShortInfo[] | SubmittedSignatureDetails[] | SubmittedSignatureShortInfo[];
  highlightedSignatureId?: string | null;
}

defineProps<Props>();

interface Emits {
  (e: 'signature-item-click', value: string): void;
}

defineEmits<Emits>();

function getItemLink(
  item: ValidSignatureShortInfo | SubmittedSignatureDetails | SubmittedSignatureShortInfo
): TypedNuxtLink['to'] {
  if (isSubmittedSignatureShortInfo(item) || isSubmittedSignatureDetails(item))
    return { name: 'verification-ballots-signatures-submitted-id', params: { id: item.id } };
  else return { name: 'verification-ballots-signatures-valid-id', params: { id: item.id } };
}
</script>
