import type { BallotPageState } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge/index';

export const ballotPagesStatusBadge: Record<BallotPageState, { variant: BadgeVariants; label: string }> = {
  created: { variant: 'info', label: 'Created' },
  aligned: { variant: 'info', label: 'Aligned' },
  soft_accepted: { variant: 'warning', label: 'Warning' },
  segmented: { variant: 'info', label: 'Segmented' },
  htr_completed: { variant: 'info', label: 'HTR Completed' },
  htr_formatted: { variant: 'info', label: 'HTR Formatted' },
  ocr_completed: { variant: 'info', label: 'OCR Completed' },
  row_crops_completed: { variant: 'info', label: 'Row Crops Completed' },
  embedding_indexed: { variant: 'info', label: 'Embedding Indexed' },
  completed: { variant: 'success', label: 'Completed' },
  rejected: { variant: 'destructive', label: 'Rejected' },
  duplicated: { variant: 'warning', label: 'Duplicated' },
  failed: { variant: 'destructive', label: 'Failed' },
  validating: { variant: 'info', label: 'Validating' },
  empty: { variant: 'default', label: 'Empty' },
};

const defaultBallotPageStatusBadge: { variant: BadgeVariants; label: string } = { variant: 'default', label: '' };

export function getBallotPagesStatusBadge(state: BallotPageState): { variant: BadgeVariants; label: string } {
  return ballotPagesStatusBadge[state] ?? { ...defaultBallotPageStatusBadge, label: snakeCaseToCapitalizedCase(state) };
}
